struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn hash22(p: vec2f) -> vec2f {
  let n = sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453;
  return fract(vec2f(n, n * 1.215));
}

fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash21(i), hash21(i + vec2f(1.0, 0.0)), u.x),
    mix(hash21(i + vec2f(0.0, 1.0)), hash21(i + vec2f(1.0, 1.0)), u.x),
    u.y
  );
}

fn fbm(p: vec2f) -> f32 {
  var v = 0.0;
  var a = 0.5;
  var q = p;
  for (var i = 0; i < 4; i++) {
    v += a * noise(q);
    q = q * 2.07 + vec2f(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

// Domain-warped intersecting waves → bright web, dark cells.
fn causticLattice(p: vec2f, t: f32) -> f32 {
  var q = p;
  q += vec2f(
    sin(q.y * 2.85 + t * 0.62) * 0.22,
    cos(q.x * 2.55 - t * 0.48) * 0.22
  );
  q += vec2f(
    sin(q.y * 5.4 - t * 0.37) * 0.09,
    cos(q.x * 4.8 + t * 0.41) * 0.09
  );

  let w1 = sin(q.x * 7.4 + t * 0.55);
  let w2 = sin(q.y * 6.6 - t * 0.47);
  let w3 = sin((q.x + q.y) * 5.15 + t * 0.31);
  let w4 = sin((q.x - q.y) * 5.85 - t * 0.39);
  let cell = abs(w1 * w2) * 0.58 + abs(w3 * w4) * 0.42;
  let web = pow(max(1.0 - cell, 0.0), 4.2);

  var r = vec2f(q.x * 0.766 - q.y * 0.643, q.x * 0.643 + q.y * 0.766);
  r += vec2f(sin(t * 0.29 + 0.8), cos(t * 0.24)) * 0.35;
  let w5 = sin(r.x * 10.6 + t * 0.72);
  let w6 = sin(r.y * 9.4 - t * 0.64);
  let web2 = pow(max(1.0 - abs(w5 * w6), 0.0), 5.1);

  var s = p * 1.35 + vec2f(0.4, -0.2);
  s += vec2f(cos(s.y * 3.2 + t * 0.44), sin(s.x * 3.6 - t * 0.51)) * 0.16;
  let w7 = sin(s.x * 4.8 - t * 0.28);
  let w8 = sin(s.y * 5.3 + t * 0.33);
  let web3 = pow(max(1.0 - abs(w7) * abs(w8), 0.0), 3.6);

  return clamp(web * 0.70 + web2 * 0.48 + web3 * 0.28, 0.0, 1.5);
}

fn godrays(uv: vec2f, t: f32) -> f32 {
  let src = vec2f(0.46, -0.08);
  let d = uv - src;
  let ang = atan2(d.x, d.y + 0.02);
  let dist = length(d * vec2f(1.15, 0.72));
  let s1 = pow(max(sin(ang * 10.0 + t * 0.13) * 0.5 + 0.5, 0.0), 3.6);
  let s2 = pow(max(sin(ang * 6.4 - t * 0.09 + 1.7) * 0.5 + 0.5, 0.0), 5.2);
  let s3 = pow(max(sin(ang * 15.5 + t * 0.07 + 0.4) * 0.5 + 0.5, 0.0), 8.0);
  let shafts = s1 * 0.62 + s2 * 0.38 + s3 * 0.22;
  let fall = exp(-dist * 1.05) * smoothstep(1.15, 0.04, uv.y);
  let haze = 0.18 + 0.82 * shafts;
  return haze * fall;
}

fn silt(uv: vec2f, t: f32) -> f32 {
  var acc = 0.0;
  var scale = vec2f(42.0, 74.0);
  var drift = t * 0.04;
  for (var i = 0; i < 3; i++) {
    let g = uv * scale + vec2f(f32(i) * 13.1, drift * (0.6 + f32(i) * 0.35));
    let id = floor(g);
    let f = fract(g) - 0.5;
    let n = hash21(id + vec2f(f32(i) * 19.0, 3.0));
    let j = hash22(id + 7.0);
    let r = 0.012 + n * 0.028;
    let spark = smoothstep(r, 0.0, length(f - (j - 0.5) * 0.42));
    acc += spark * step(0.86 + f32(i) * 0.03, n) * (0.35 + 0.65 * n);
    scale *= 1.85;
  }
  return clamp(acc, 0.0, 1.0);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  let aspect = 720.0 / 1280.0;
  let p = vec2f((uv.x - 0.5) / aspect, uv.y);

  // Depth: y=0 is the surface (top-origin), y=1 the abyss.
  let depth = clamp(uv.y, 0.0, 1.0);
  let abyss = vec3f(0.004, 0.018, 0.055);
  let deep = vec3f(0.008, 0.055, 0.118);
  let mid = vec3f(0.018, 0.145, 0.210);
  let near = vec3f(0.055, 0.320, 0.355);
  var col = abyss;
  col = mix(col, deep, smoothstep(1.0, 0.62, depth));
  col = mix(col, mid, smoothstep(0.72, 0.28, depth));
  col = mix(col, near, smoothstep(0.32, 0.0, depth) * 0.85);

  // Soft volume noise so the water is not a flat wash.
  let vol = fbm(uv * vec2f(3.2, 5.6) + vec2f(t * 0.03, 0.0));
  col *= 0.88 + 0.18 * vol;
  col += vec3f(0.01, 0.04, 0.05) * vol * (1.0 - depth);

  // Caustic lattice, stronger toward the surface, fading in the abyss.
  let latUv = vec2f(p.x * 1.15, uv.y * 2.05 + 0.15);
  let cau = causticLattice(latUv, t);
  let cauDeep = causticLattice(latUv * 0.62 + vec2f(2.4, 1.1), t * 0.7 + 1.8);
  let depthGate = exp(-depth * 1.55) * (0.35 + 0.65 * smoothstep(1.0, 0.18, depth));
  let cauAmt = (cau * 0.78 + cauDeep * 0.32) * depthGate;
  let cauCol = vec3f(0.28, 0.92, 0.86);
  let cauHot = vec3f(0.72, 0.98, 0.94);
  col += cauCol * cauAmt * 0.72;
  col += cauHot * pow(clamp(cauAmt, 0.0, 1.0), 3.2) * 0.55;

  // Teal-cyan godrays from a surface sun just above the frame.
  let rays = godrays(uv, t);
  let rayCol = vec3f(0.38, 0.88, 0.84);
  col += rayCol * rays * 0.55;
  col += vec3f(0.70, 0.96, 0.93) * pow(rays, 2.4) * 0.35;
  col += cauCol * rays * cauAmt * 0.40;

  // Looking up: bright refracted surface band.
  let surf = smoothstep(0.22, 0.0, depth);
  let swell = sin(uv.x * 18.0 + t * 0.9) * 0.012 + sin(uv.x * 9.0 - t * 0.55) * 0.018;
  let meniscus = smoothstep(0.055 + swell, 0.0, depth);
  col += vec3f(0.42, 0.86, 0.82) * surf * 0.38;
  col += vec3f(0.85, 0.98, 0.96) * meniscus * 0.62;
  let glitter = pow(max(causticLattice(vec2f(uv.x * 8.0, uv.y * 14.0), t * 1.1), 0.0), 6.0);
  col += vec3f(0.90, 1.0, 0.98) * glitter * surf * 0.45;

  // Faint silt motes drifting in the column.
  let motes = silt(uv, t);
  col += vec3f(0.55, 0.82, 0.80) * motes * (0.18 + 0.22 * (1.0 - depth));

  // Soft center lift + edge falloff (being in a place, not a plate).
  let vig = smoothstep(1.25, 0.22, length(vec2f((uv.x - 0.5) * 1.15, (uv.y - 0.28) * 0.85)));
  col *= 0.62 + 0.38 * vig;
  col += vec3f(0.03, 0.10, 0.12) * (1.0 - vig) * 0.15;

  // Mild teal grade, keep it wet not neon.
  col = mix(col, vec3f(col.b * 0.55, col.g, col.b * 1.05 + col.g * 0.08), 0.18);
  col = clamp(col, vec3f(0.0), vec3f(1.0));
  return vec4f(col, 1.0);
}
